# ============================================================================= # SpotifyDL v2 — Windows PowerShell Push & Deploy Script # # Usage: #   $env:GITHUB_TOKEN = 'ghp_xxxxxxxx' #   .scripts/push-and-deploy.ps1 # ============================================================================= param( [string]$GithubUser = '', [string]$RepoName = 'spotifydl-v2', [string]$AppName = 'spotifydl-v2' ) # Colors $Red = 'Red' $Green = 'Green' $Blue = 'Cyan' $Yellow = 'Yellow' # Check token if (-not $env:GITHUB_TOKEN) { Write-Host 'ERROR: GITHUB_TOKEN environment variable not set!' -ForegroundColor $Red Write-Host '' Write-Host 'Set it first:' -ForegroundColor $Yellow Write-Host '  $env:GITHUB_TOKEN = ghp_xxxxxxxxxxxxxxxx' -ForegroundColor $Yellow Write-Host '' exit 1 } # Banner Write-Host '' Write-Host '╔═══════════════════════════════════════════════════════════════╗' -ForegroundColor $Blue Write-Host '║ 🎵 SpotifyDL v2 — Push & Deploy (Windows) ║' -ForegroundColor $Blue Write-Host '╚═══════════════════════════════════════════════════════════════╝' -ForegroundColor $Blue Write-Host '' # Verify token Write-Host '🔐 Verifying GitHub token...' -ForegroundColor $Blue try { $headers = @{ Authorization = 'token ' + $env:GITHUB_TOKEN } $user = Invoke-RestMethod -Uri 'https://api.github.com/user' -Headers $headers -ErrorAction Stop $GithubUser = $user.login Write-Host ('✅ Token verified for: ' + $GithubUser) -ForegroundColor $Green } catch { Write-Host ('❌ Invalid token: ' + $_.Exception.Message) -ForegroundColor $Red exit 1 } # Check git if (-not (Get-Command git -ErrorAction SilentlyContinue)) { Write-Host '❌ git not found. Install from https://git-scm.com' -ForegroundColor $Red exit 1 } # Check if in repo if (-not (Test-Path '.git')) { Write-Host '❌ Not a git repository. Run from project root.' -ForegroundColor $Red exit 1 } # Check remote $remoteUrl = 'https://' + $GithubUser + ':' + $env:GITHUB_TOKEN + '@github.com/' + $GithubUser + '/' + $RepoName + '.git' $existingRemote = git remote get-url origin 2>$null if ($existingRemote) { Write-Host ('📝 Updating remote to: ' + $remoteUrl) -ForegroundColor $Blue git remote set-url origin $remoteUrl } else { Write-Host ('📝 Adding remote: ' + $remoteUrl) -ForegroundColor $Blue git remote add origin $remoteUrl } # Commit & push Write-Host '' Write-Host '📤 Committing and pushing to GitHub...' -ForegroundColor $Blue git add -A $status = git status --short if ($status) { git commit -m 'Auto-deploy from Windows' Write-Host '✅ Changes committed' -ForegroundColor $Green } else { Write-Host '⚠️ No changes to commit' -ForegroundColor $Yellow } git push -u origin main Write-Host '✅ Pushed to GitHub!' -ForegroundColor $Green # Fly.io deploy Write-Host '' Write-Host '🚀 Deploying to Fly.io...' -ForegroundColor $Blue $flyExists = Get-Command flyctl -ErrorAction SilentlyContinue if (-not $flyExists) { Write-Host '⚠️ flyctl not found. Install from https://fly.io/docs/hands-on/install-flyctl/' -ForegroundColor $Yellow } else { # Check if app exists $apps = flyctl apps list 2>$null | Select-String $AppName if (-not $apps) { Write-Host '📦 Creating Fly.io app...' -ForegroundColor $Blue flyctl launch --name $AppName --region fra --dockerfile Dockerfile --no-deploy } # Deploy Write-Host '🚢 Deploying...' -ForegroundColor $Blue flyctl deploy --app $AppName Write-Host '✅ Fly.io deploy complete!' -ForegroundColor $Green # Get info Write-Host '' Write-Host '📊 App Status:' -ForegroundColor $Blue flyctl status --app $AppName Write-Host '' Write-Host '🌐 Your app URL: https://' + $AppName + '.fly.dev' -ForegroundColor $Green Write-Host '' Write-Host '📋 DNS Records for dyrakarmy.eu:' -ForegroundColor $Yellow Write-Host '  Get IPs with: flyctl ips list --app ' + $AppName -ForegroundColor $Yellow } # Render deploy Write-Host '' Write-Host '🚀 Triggering Render deploy...' -ForegroundColor $Blue if ($env:RENDER_API_KEY -and $env:RENDER_SERVICE_ID) { try { Invoke-RestMethod -Uri ('https://api.render.com/v1/services/' + $env:RENDER_SERVICE_ID + '/deploys') -Method Post -Headers @{ Authorization = 'Bearer ' + $env:RENDER_API_KEY; 'Content-Type' = 'application/json' } -Body '{clearCache: true}' Write-Host '✅ Render deploy triggered!' -ForegroundColor $Green } catch { Write-Host ('⚠️ Render deploy failed: ' + $_.Exception.Message) -ForegroundColor $Yellow } } else { Write-Host '⚠️ RENDER_API_KEY or RENDER_SERVICE_ID not set. Skipping Render.' -ForegroundColor $Yellow } # Final Write-Host '' Write-Host '╔═══════════════════════════════════════════════════════════════╗' -ForegroundColor $Green Write-Host '║ ✅ DEPLOY COMPLETE! ║' -ForegroundColor $Green Write-Host '╚═══════════════════════════════════════════════════════════════╝' -ForegroundColor $Green Write-Host '' Write-Host ('🌐 Primary: https://' + $AppName + '.fly.dev') -ForegroundColor $Green Write-Host '🌐 Mirror: https://dashboard.render.com (check status)' -ForegroundColor $Green Write-Host '' Write-Host 'Next steps:' -ForegroundColor $Yellow Write-Host '  1. Add DNS A/AAAA records for dyrakarmy.eu' -ForegroundColor $Yellow Write-Host '  2. Add CNAME www → ' + $AppName + '.fly.dev' -ForegroundColor $Yellow Write-Host '  3. Run: flyctl logs --app ' + $AppName -ForegroundColor $Yellow